<style>.cat-head{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:28px;padding:20px 24px;border:1px solid var(--border);border-radius:20px;background:var(--muted)}.cat-head form,.cat-head .btn{margin:0}.event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.event-card{display:flex;flex-direction:column;padding:24px;border:1px solid var(--border);border-radius:24px;background:#fff}.event-card h2{margin:9px 0}.event-card p{color:var(--muted-foreground)}.event-state{display:inline-flex;width:max-content;padding:5px 9px;border-radius:999px;background:rgba(145,208,37,.15);color:var(--primary-deep);font-size:12px;font-weight:700}.event-more{margin-top:auto;padding-top:12px;color:var(--primary-deep);font-weight:700}@media(max-width:900px){.event-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.cat-head{align-items:flex-start;flex-direction:column}.event-grid{grid-template-columns:1fr}}</style>
<section class="hero"><div class="wrap"><span class="section-label">Formazione tecnica riservata</span><h1>Campus CAT</h1><p>Eventi, aggiornamenti e storico delle attività dedicate ai Centri Assistenza Tecnica IDEMA.</p></div></section>
<section class="content"><div class="wrap"><div class="cat-head"><div><strong><?=e($catUser['company_name'])?></strong><br><span class="meta"><?=e($catUser['contact_first_name'].' '.$catUser['contact_last_name'])?></span></div><form method="post" action="/idemaclima/campus/cat/logout"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><button class="btn" type="submit">Esci</button></form></div><div class="event-grid"><?php foreach($events as $event):$past=strtotime((string)$event['starts_at'])<time();?><a class="event-card" href="/idemaclima/campus/cat/<?=e($event['slug'])?>"><span class="section-label"><?=e($event['category']?:'Evento CAT')?></span><h2><?=e($event['title'])?></h2><span class="meta"><?=e(date('d/m/Y · H:i',strtotime((string)$event['starts_at'])))?><?=!empty($event['location'])?' · '.e($event['location']):''?></span><?php if(!empty($event['short_description'])):?><p><?=e($event['short_description'])?></p><?php endif;?><?php if(!empty($event['user_status'])):?><span class="event-state"><?=['registered'=>'Iscritto','confirmed'=>'Confermato','waitlist'=>'Lista d’attesa','cancelled'=>'Iscrizione annullata'][$event['user_status']]??e($event['user_status'])?></span><?php elseif($past):?><span class="event-state">Evento concluso</span><?php endif;?><span class="event-more">Apri evento →</span></a><?php endforeach;?><?php if(!$events):?><p>Nessun evento CAT disponibile.</p><?php endif;?></div></div></section>
